package com.agentguard.service;
import com.agentguard.dto.*; import com.agentguard.entity.User; import com.agentguard.exception.*; import com.agentguard.repository.UserRepository; import org.junit.jupiter.api.*; import org.mockito.*; import java.math.BigDecimal; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class UserServiceTest { @Mock UserRepository users; @InjectMocks UserService service; @BeforeEach void setup(){MockitoAnnotations.openMocks(this);} @Test void createsUser(){when(users.existsByEmailIgnoreCase("a@example.com")).thenReturn(false);when(users.save(any())).thenAnswer(i->{User u=i.getArgument(0);return u;}); UserResponse response=service.create(new CreateUserRequest(" Ada ","A@EXAMPLE.COM",new BigDecimal("100.00"),new BigDecimal("25.00"))); assertThat(response.name()).isEqualTo("Ada");assertThat(response.email()).isEqualTo("a@example.com");verify(users).save(any(User.class));} @Test void rejectsDuplicateEmail(){when(users.existsByEmailIgnoreCase("a@example.com")).thenReturn(true);assertThatThrownBy(()->service.create(new CreateUserRequest("Ada","a@example.com",new BigDecimal("100"),new BigDecimal("25")))).isInstanceOf(DuplicateResourceException.class);verify(users,never()).save(any());} @Test void getsUser(){User u=new User();u.setName("Ada");u.setEmail("a@example.com");u.setSpendingLimit(new BigDecimal("100"));u.setHourlySpendingLimit(new BigDecimal("25"));when(users.findById(1L)).thenReturn(Optional.of(u));assertThat(service.getById(1L).email()).isEqualTo("a@example.com");} }
